mapper.select:
select *
from (
select product_part_sign name, primary_key, state, 'productPart' source_table, model, pcs, update_time ,remark
from ${productPart} a
where enterprise_code = #{enterpriseCode}
and delete_flag = false


    and product_part_sign like '%'|| #{condition.keyword} ||'%'



    and model like '%'|| #{condition.model} ||'%'





        and (

        not exists (
        select 1 from ${dynamicTableNameProxy.productsPriceNew} b
        where b.source_id = a.primary_key and b.source_table ='productPart'
        and b.enterprise_code = ${dynamicTableNameProxy.enterpriseCode}
        and b.delete_flag = false
        )

        or

        exists(
        select 1 from (
        select Copy_State ,ROW_NUMBER() OVER (ORDER BY create_time DESC, id DESC) AS id
        from ${dynamicTableNameProxy.productsPriceNew} b
        where b.source_id = a.primary_key and b.source_table ='productPart'
        and b.enterprise_code = ${dynamicTableNameProxy.enterpriseCode}
        and b.delete_flag = false
        order by create_Time desc ,id desc limit 1
        ) aa where aa.Copy_State=true and aa.id=1
        )

        )





        and exists(
        select 1 from (
        select Copy_State ,ROW_NUMBER() OVER (ORDER BY create_time DESC, id DESC) AS id
        from ${dynamicTableNameProxy.productsPriceNew} b
        where b.source_id = a.primary_key and b.source_table ='productPart'
        and b.enterprise_code = ${dynamicTableNameProxy.enterpriseCode}
        and b.delete_flag = false
        ) aa where aa.Copy_State=false and aa.id=1
        )




    and exists(
    select 1 from ${productsPriceNewTable} b where a.primary_key = b.source_Id and b.source_table='productPart'


        and b.operate_name like '%'|| #{condition.personName} ||'%'



        and b.operate_code = #{condition.personCode}

    )


    and ${dynamicTableNameProxy.getXiHangPartQuery("a.primary_key","xihang",condition.partUnityNo)}


and ${dynamicTableNameProxy.getProductPartSearchObj("a.primary_key",condition.searchName)}

and attribute = 1
) as a

where 1=1


    and primary_key in

        #{id}



order by update_time desc ,primary_key desc

select * from ${productsPriceNewTable}
where enterprise_code = #{enterpriseCode}
and delete_flag = false
and ( source_id,source_table ) in (

    (#{id.code},#{id.name})

)
order by create_Time desc ,id desc

select *
from ${productsPriceNewTable}
where enterprise_code = #{enterpriseCode}
  and delete_flag = false
  and source_id = #{condition.code}
  and source_table = #{condition.name}
order by create_Time desc ,id desc  limit 1

mapper.update:
update ${tableName}
set remark      = #{record.remark},
    update_time = now()
where primary_key = #{record.id}

mapper.select:
select *
from ${tableName}
where enterprise_code = #{enterpriseCode}
  and primary_key = #{id}
order by create_Time desc, id desc limit 1
